import React, { useEffect, useState } from 'react';
import { Alert, SafeAreaView, View } from 'react-native';
import type { MainStackNavigationProp } from '@src/presentation/navigation/MainNavigator';
import { useNavigation } from '@react-navigation/native';
import { useSelector } from 'react-redux';
// import { selectStatus } from './RegisterCVPSelector';
import useCSS from '@src/presentation/style/index';
import { useDispatch } from '@src/lib/redux';
// import { fetchLocationDetail } from '@src/presentation/weather/WeatherSearch';
import { IS_IOS, Storage, STORAGE_KEY, useTranslation } from '@core/service';
import { ScrollView } from 'react-native-gesture-handler';
import { WebView } from 'react-native-webview';
import { createStyles, GradientButton, LoadingBlockerView, SimpleHeader, Text } from '@core/ui';
// import { LoanRegisterSlice } from '../register_confirm/redux/slice';
import { fetchLocationDetail } from '@src/presentation/weather/WeatherSearch';
import { SCREEN_HEIGHT } from '@gorhom/bottom-sheet';
import { fetchClientInfo } from '@src/presentation/loan_products/thunk';
import { GetClientInfoPayload } from '@src/application/common/get_client_info/get_client_info_payload';
import { selectClientNo } from '@src/presentation/loan_products/selector';
import { ClientInfo } from '@src/domain/entities/common/clientInfo';
import { ACCESS_TOKEN_INVALID, DIN } from '@src/utils/constants';
import { selectStatus, selectError } from '@src/presentation/loan_products/selector';

const CollateralCVPScreen: React.FC = () => {
    const css = useCSS();
    const error = useSelector(selectError);
    const status = useSelector(selectStatus);
    const navigation = useNavigation<MainStackNavigationProp>();
    const dispatch = useDispatch();
    const clientNo = useSelector(selectClientNo);

    const { t } = useTranslation(['module_collateral']);

    const handlePressSubmit = () => {
        dispatch(fetchClientInfo({ clientNo } as GetClientInfoPayload['data'])).then((res) => {
            const data = (res.payload as ClientInfo).data;
            const { clientType } = data;
            if (clientType === DIN && error !== ACCESS_TOKEN_INVALID && status !== 'loading') {
                navigation.navigate('collateral_accounts');
            }
        });
    };

    return (
        <View style={[css.relative, css.flex_1]}>
            <WebView
                source={{ uri: 'https://chic-starburst-059945.netlify.app/cvp_loan_collateral/index.html' }}
                allowsInlineMediaPlayback={true}
                mediaPlaybackRequiresUserAction={false}
                style={[{ minHeight: SCREEN_HEIGHT }]}
            />
            <View style={[css.absolute, css.shrink_0, { top: 0, left: 0, bottom: 0, right: 0 }]}>
                <SafeAreaView style={[css.flex_1]}>
                    <SimpleHeader
                        allowGoBack
                        onBackPress={() => {
                            navigation.goBack();
                        }}
                    />
                </SafeAreaView>
                <View style={[css.mt_auto, css.p_medium, { backgroundColor: 'rgba(255,255,255,.5)' }]}>
                    <SafeAreaView>
                        <GradientButton gradientProps={{ type: 'primary' }} title={t('screen_cvp.label_submit')} onPress={handlePressSubmit} />
                    </SafeAreaView>
                </View>
            </View>

            {status === 'loading' ? <LoadingBlockerView containerStyle={{ backgroundColor: 'rgba(255,255,255,0.5)', zIndex: 100000 }} /> : null}
        </View>
    );
};

export default CollateralCVPScreen;
