import { TYPES } from '@src/di/types/types';
import { inject } from 'inversify';
import type { ICmsRegisterStaticDataRepository } from '@src/domain/interfaces/cms/loan_register/registerStaticData';

export class GetCmsRegisterStaticDataHandler {
    private readonly _cmsRegisterStaticDataRepository: ICmsRegisterStaticDataRepository;

    constructor(
        @inject(TYPES.ICmsRegisterStaticDataRepository) cmsRegisterStaticDataRepository: ICmsRegisterStaticDataRepository,
    ) {
        this._cmsRegisterStaticDataRepository = cmsRegisterStaticDataRepository;
    }

    handle(segment: string) {
        return this._cmsRegisterStaticDataRepository.getCmsRegisterStaticData(segment)
    }
}
